import{_ as p,a0 as o,w as r,s as d,ao as e,I as i,x as s,a1 as l,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"Git 提交是差异、快照还是历史记录？ | LCTT x X-CMD","titleTemplate":false,"description":"Git 提交是差异、快照还是历史记录？ | LCTT (202401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Git 提交是差异、快照还是历史记录？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Git 提交是差异、快照还是历史记录？ | LCTT (202401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202401/20240105 Do we think of git commits as diffs, snapshots, and-or histories","title":"Git 提交是差异、快照还是历史记录？","tag":"202401","desc":""},"relativePath":"202401/20240105 Do we think of git commits as diffs, snapshots, and-or histories.md","filePath":"[post].md"}'),f={name:"202401/20240105 Do we think of git commits as diffs, snapshots, and-or histories.md"};function b(u,a,m,g,h,k){const t=o("Link");return r(),d("div",null,[a[34]||(a[34]=e('<h1 id="git-提交是差异、快照还是历史记录" tabindex="-1">Git 提交是差异、快照还是历史记录？ <a class="header-anchor" href="#git-提交是差异、快照还是历史记录" aria-label="Permalink to “Git 提交是差异、快照还是历史记录？”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202401/21/184647vzxemtv993tjgmze.jpg" alt=""></p><p>大家好！我一直在慢慢摸索如何解释 Git 中的各个核心理念（提交、分支、远程、暂存区），而提交这个概念却出奇地棘手。</p><p>要明白 Git 提交是如何实现的对我来说相当简单（这些都是确定的！我可以直接查看！），但是要弄清楚别人是怎么看待提交的却相当困难。所以，就像我最近一直在做的那样，我在 Mastodon 上问了一些问题。</p><h3 id="大家是怎么看待-git-提交的" tabindex="-1">大家是怎么看待 Git 提交的？ <a class="header-anchor" href="#大家是怎么看待-git-提交的" aria-label="Permalink to “大家是怎么看待 Git 提交的？”">​</a></h3>',5)),i("p",null,[a[1]||(a[1]=s("我进行了一个 ",-1)),l(t,{href:"https://social.jvns.ca/@b0rk/111563158717698550"},{default:n(()=>[...a[0]||(a[0]=[s("非常不科学的调查",-1)])]),_:1}),a[2]||(a[2]=s("，询问大家是怎么看待 Git 提交的：是快照、差异，还是所有之前提交的列表？（当然，把它看作这三者都是合理的，但我很好奇人们的 ",-1)),a[3]||(a[3]=i("em",null,"主要",-1)),a[4]||(a[4]=s(" 观点）。这是调查结果：",-1))]),a[35]||(a[35]=e(`<p><img src="https://jvns.ca/images/git-commit-poll.png" alt=""></p><p>结果是：</p><ul><li>51% 差异</li><li>42% 快照</li><li>4% 所有之前的提交的历史记录</li><li>3% “其他”</li></ul><p>我很惊讶差异和快照两个选项的比例如此接近。人们还提出了一些有趣但相互矛盾的观点，比如 “在我看来，提交是一个差异，但我认为它实际上是以快照的形式实现的” 和 “在我看来，提交是一个快照，但我认为它实际上是以差异的形式实现的”。关于提交的实际实现方式，我们稍后再详谈。</p><p>在我们进一步讨论之前：我们的说 “一个差异” 或 “一个快照” 都是什么意思？</p><h3 id="什么是差异" tabindex="-1">什么是差异？ <a class="header-anchor" href="#什么是差异" aria-label="Permalink to “什么是差异？”">​</a></h3><p>我说的“差异”可能相当明显：差异就是你在运行 <code>git show COMMIT_ID</code> 时得到的东西。例如，这是一个 rbspy 项目中的拼写错误修复：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>diff --git a/src/ui/summary.rs b/src/ui/summary.rs</span></span>
<span class="line"><span>index 5c4ff9c..3ce9b3b 100644</span></span>
<span class="line"><span>--- a/src/ui/summary.rs</span></span>
<span class="line"><span>+++ b/src/ui/summary.rs</span></span>
<span class="line"><span>@@ -160,7 +160,7 @@ mod tests {</span></span>
<span class="line"><span>  &quot;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>          let mut buf: Vec&lt;u8&gt; = Vec::new();</span></span>
<span class="line"><span>-        stats.write(&amp;mut buf).expect(&quot;Callgrind write failed&quot;);</span></span>
<span class="line"><span>+        stats.write(&amp;mut buf).expect(&quot;summary write failed&quot;);</span></span>
<span class="line"><span>          let actual = String::from_utf8(buf).expect(&quot;summary output not utf8&quot;);</span></span>
<span class="line"><span>          assert_eq!(actual, expected, &quot;Unexpected summary output&quot;);</span></span>
<span class="line"><span>      }</span></span></code></pre></div>`,8)),i("p",null,[a[6]||(a[6]=s("你可以在 GitHub 上看到它： ",-1)),l(t,{href:"https://github.com/rbspy/rbspy/commit/24ad81d2439f9e63dd91cc1126ca1bb5d3a4da5b"},{default:n(()=>[...a[5]||(a[5]=[s("https://github.com/rbspy/rbspy/commit/24ad81d2439f9e63dd91cc1126ca1bb5d3a4da5b",-1)])]),_:1})]),a[36]||(a[36]=i("h3",{id:"什么是快照",tabindex:"-1"},[s("什么是快照？ "),i("a",{class:"header-anchor",href:"#什么是快照","aria-label":"Permalink to “什么是快照？”"},"​")],-1)),a[37]||(a[37]=i("p",null,[s("我说的 “快照” 是指 “当你运行 "),i("code",null,"git checkout COMMIT_ID"),s(" 时得到的所有文件”。")],-1)),a[38]||(a[38]=i("p",null,"Git 通常将提交的文件列表称为 “树”（如“目录树”），你可以在 GitHub 上看到上述提交的所有文件：",-1)),i("p",null,[l(t,{href:"https://github.com/rbspy/rbspy/tree/24ad81d2439f9e63dd91cc1126ca1bb5d3a4da5b"},{default:n(()=>[...a[7]||(a[7]=[s("https://github.com/rbspy/rbspy/tree/24ad81d2439f9e63dd91cc1126ca1bb5d3a4da5b",-1)])]),_:1}),a[8]||(a[8]=s("（它是 ",-1)),a[9]||(a[9]=i("code",null,"/tree/",-1)),a[10]||(a[10]=s(" 而不是 ",-1)),a[11]||(a[11]=i("code",null,"/commit/",-1)),a[12]||(a[12]=s("）",-1))]),a[39]||(a[39]=i("h3",{id:"git-是如何实现的-真的是正确的解释方式吗",tabindex:"-1"},[s("“Git 是如何实现的”真的是正确的解释方式吗？ "),i("a",{class:"header-anchor",href:"#git-是如何实现的-真的是正确的解释方式吗","aria-label":"Permalink to ““Git 是如何实现的”真的是正确的解释方式吗？”"},"​")],-1)),a[40]||(a[40]=i("p",null,[s("我最常听到的关于学习 Git 的建议大概是 “只要学会 Git 在内部是如何表示事物的，一切都会变得清晰明了”。我显然非常喜欢这种观点（如果你花了一些时间阅读这个博客，你就会知道我 "),i("em",null,"喜欢"),s(" 思考事物在内部是如何实现的）。")],-1)),a[41]||(a[41]=i("p",null,"但是作为一个学习 Git 的方法，它并没有我希望的那么成功！通常我会兴奋地开始解释 “好的，所以 Git 提交是一个快照，它有一个指向它的父提交的指针，然后一个分支是一个指向提交的指针，然后……”，但是我试图帮助的人会告诉我，他们并没有真正发现这个解释有多有用，他们仍然不明白。所以我一直在考虑其他方案。",-1)),a[42]||(a[42]=i("p",null,"但是让我们还是先谈谈内部实现吧。",-1)),a[43]||(a[43]=i("h3",{id:"git-是如何在内部表示提交的-——-快照",tabindex:"-1"},[s("Git 是如何在内部表示提交的 —— 快照 "),i("a",{class:"header-anchor",href:"#git-是如何在内部表示提交的-——-快照","aria-label":"Permalink to “Git 是如何在内部表示提交的 —— 快照”"},"​")],-1)),i("p",null,[a[14]||(a[14]=s("在内部，Git 将提交表示为快照（它存储每个文件当前版本的 “树”）。我在 ",-1)),l(t,{href:"https://jvns.ca/blog/2023/09/14/in-a-git-repository--where-do-your-files-live-/"},{default:n(()=>[...a[13]||(a[13]=[s("在一个 Git 仓库中，你的文件在哪里？",-1)])]),_:1}),a[15]||(a[15]=s(" 中写过这个，但下面是一个非常快速的内部格式概述。",-1))]),a[44]||(a[44]=e(`<p>这是一个提交的表示方式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git cat-file -p 24ad81d2439f9e63dd91cc1126ca1bb5d3a4da5b</span></span>
<span class="line"><span>tree e197a79bef523842c91ee06fa19a51446975ec35</span></span>
<span class="line"><span>parent 26707359cdf0c2db66eb1216bf7ff00eac782f65</span></span>
<span class="line"><span>author Adam Jensen &lt;adam@acj.sh&gt; 1672104452 -0500</span></span>
<span class="line"><span>committer Adam Jensen &lt;adam@acj.sh&gt; 1672104890 -0500</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Fix typo in expectation message</span></span></code></pre></div><p>以及，当我们查看这个树对象时，我们会看到这个提交中仓库根目录下每个文件/子目录的列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git cat-file -p e197a79bef523842c91ee06fa19a51446975ec35</span></span>
<span class="line"><span>040000 tree 2fcc102acd27df8f24ddc3867b6756ac554b33ef    .cargo</span></span>
<span class="line"><span>040000 tree 7714769e97c483edb052ea14e7500735c04713eb    .github</span></span>
<span class="line"><span>100644 blob ebb410eb8266a8d6fbde8a9ffaf5db54a5fc979a    .gitignore</span></span>
<span class="line"><span>100644 blob fa1edfb73ce93054fe32d4eb35a5c4bee68c5bf5    ARCHITECTURE.md</span></span>
<span class="line"><span>100644 blob 9c1883ee31f4fa8b6546a7226754cfc84ada5726    CODE_OF_CONDUCT.md</span></span>
<span class="line"><span>100644 blob 9fac1017cb65883554f821914fac3fb713008a34    CONTRIBUTORS.md</span></span>
<span class="line"><span>100644 blob b009175dbcbc186fb8066344c0e899c3104f43e5    Cargo.lock</span></span>
<span class="line"><span>100644 blob 94b87cd2940697288e4f18530c5933f3110b405b    Cargo.toml</span></span></code></pre></div><p>这意味着检出一个 Git 提交总是很快的：对 Git 来说，检出昨天的提交和检出 100 万个提交之前的提交一样容易。Git 永远不需要重新应用 10000 个差异来确定当前状态，因为提交根本就不是以差异的形式存储的。</p><h3 id="快照使用-packfile-进行压缩" tabindex="-1">快照使用 packfile 进行压缩 <a class="header-anchor" href="#快照使用-packfile-进行压缩" aria-label="Permalink to “快照使用 packfile 进行压缩”">​</a></h3><p>我刚刚提到了 Git 提交是一个快照，但是，当有人说 “在我看来，提交是一个快照，但我认为它在实现上是一个差异” 时，这其实也是对的！Git 提交并不是以你可能习惯的差异的形式表示的（它们不是以与上一个提交的差异的形式存储在磁盘上的），但基本的直觉是，如果你要对一个 10,000 行的文件编辑 500 次，那么存储 500 份文件的效率会很低。</p><p>Git 有一个将文件以差异的形式存储的方法。这被称为 “packfile”，Git 会定期进行垃圾回收，将你的数据压缩成 packfile 以节省磁盘空间。当你 <code>git clone</code> 一个仓库时，Git 也会压缩数据。</p>`,8)),i("p",null,[a[17]||(a[17]=s("这里，我没有足够的篇幅来完整地解释 packfile 是如何工作的（Aditya Mukerjee 的 《",-1)),l(t,{href:"https://codewords.recurse.com/issues/three/unpacking-git-packfiles"},{default:n(()=>[...a[16]||(a[16]=[s("解压 Git packfile",-1)])]),_:1}),a[18]||(a[18]=s("》是我最喜欢的解释它们是如何工作的文章）。不过，我可以在这里简单总结一下我对 deltas 工作原理的理解，以及它们与 diff 的区别：",-1))]),a[45]||(a[45]=e('<ul><li>对象存储为 “原始文件” 和一个 “<ruby>变化量<rt>delta</rt></ruby>” 的引用</li><li>变化量是一系列例如 “读取第 0 到 100 字节，然后插入字节 ‘hello there’，然后读取第 120 到 200 字节” 的指令。它从原始文件中拼凑出新的文本。所以没有 “删除” 的概念，只有复制和添加。</li><li>我认为变化量的层次较少：我不知道如何检查 Git 究竟要经过多少层变化量才能得到一个给定的对象，但我的印象是通常不会很多。可能少于 10 层？不过，我很想知道如何才能真正查出来。</li><li>原始文件不一定来自上一个提交，它可以是任何东西。也许它甚至可以来自一个更晚的提交？我不确定。</li><li>没有一个 “正确的” 算法来计算变化量，Git 只是有一些近似的启发式算法</li></ul><h3 id="当你查看差异时-实际上发生了一些奇怪的事情" tabindex="-1">当你查看差异时，实际上发生了一些奇怪的事情 <a class="header-anchor" href="#当你查看差异时-实际上发生了一些奇怪的事情" aria-label="Permalink to “当你查看差异时，实际上发生了一些奇怪的事情”">​</a></h3><p>当我们运行 <code>git show SOME_COMMIT</code> 来查看某个提交的差异时，实际上发生的事情有点反直觉。我的理解是：</p><ol><li>Git 会在 packfile 中查找并应用变化量来重建该提交和其父提交的树。</li><li>Git 会对两个目录树（当前提交的目录树和父提交的目录树）进行差异比较。通常这很快，因为几乎所有的文件都是完全一样的，所以 git 只需比较相同文件的哈希值就可以了，几乎所有时候都不用做什么。</li><li>最后 Git 会展示差异</li></ol><p>所以，Git 会将变化量转换为快照，然后计算差异。它感觉有点奇怪，因为它从一个类似差异的东西开始，最终得到另一个类似差异的东西，但是变化量和差异实际上是完全不同的，所以这是说得通的。</p><p>也就是说，我认为 Git 将提交存储为快照，而 packfile 只是一个实现细节，目的是节省磁盘空间并加快克隆速度。我其实从来没必要知道 packfile 是如何工作的，但它确实能帮助我理解 Git 是如何在不占用太多磁盘空间的情况下将提交快照化的。</p><h3 id="一个-错误的-git-理解-提交是差异" tabindex="-1">一个 “错误的” Git 理解：提交是差异 <a class="header-anchor" href="#一个-错误的-git-理解-提交是差异" aria-label="Permalink to “一个 “错误的” Git 理解：提交是差异”">​</a></h3><p>我认为一个相当常见的，对 Git 的 “错误” 的理解是：</p><ul><li>提交是以基于上一个提交的差异的形式存储的（加上指向父提交的指针和作者和消息）。</li><li>要获取提交的当前状态，Git 需要从头开始重新应用所有之前的提交。</li></ul><p>这个理解当然是错误的（在现实中，提交是以快照的形式存储的，差异是从这些快照计算出来的），但是对我来说它似乎非常有用而且有意义！在考虑合并提交时会有一点奇怪，但是或许我们可以说这只是基于合并提交的第一个父提交的差异。</p><p>我认为这个错误的理解有的时候非常有用，而且对于日常 Git 使用来说它似乎并没有什么问题。我真的很喜欢它将我们最常使用的东西（差异）作为最基本的元素——它对我来说非常直观。</p><p>我也一直在思考一些其他有用但 “错误” 的 Git 理解，比如：</p><ul><li>提交信息可以被编辑（实际上不能，你只是复制了一个相同的提交然后给了它一个新的信息，旧的提交仍然存在）</li><li>提交可以被移动到一个不同的基础上（类似地，它们是被复制了）</li></ul><p>我认为有一系列非常有意义的、 “错误” 的对 Git 的理解，它们在很大程度上都受到 Git 用户界面的支持，并且在大多数情况下都不会产生什么问题。但是当你想要撤销一个更改或者出现问题时，它可能会变得混乱。</p><h3 id="将提交视为差异的一些优势" tabindex="-1">将提交视为差异的一些优势 <a class="header-anchor" href="#将提交视为差异的一些优势" aria-label="Permalink to “将提交视为差异的一些优势”">​</a></h3><p>就算我知道在 Git 中提交是快照，我可能大部分时间也都将它们视为差异，因为：</p><ul><li>大多时候我都在关注我正在做的 <strong>更改</strong> —— 如果我只是改变了一行代码，显然我主要是在考虑那一行代码而不是整个代码库的当前状态</li><li>点击 GitHub 上的 Git 提交或者使用 <code>git show</code> 时，你会看到差异，所以这只是我习惯看到的东西</li><li>我经常使用变基，它就是关于重新应用差异的</li></ul><h3 id="将提交视为快照的一些优势" tabindex="-1">将提交视为快照的一些优势 <a class="header-anchor" href="#将提交视为快照的一些优势" aria-label="Permalink to “将提交视为快照的一些优势”">​</a></h3><p>但是我有时也会将提交视为快照，因为：</p><ul><li>Git 经常对文件的移动感到困惑：有时我移动了一个文件并编辑了它，Git 无法识别它是否被移动过，而是显示为 “删除了 old.py，添加了 new.py”。这是因为 Git 只存储快照，所以当它显示 “移动 old.py -&gt; new.py” 时，只是猜测，因为 old.py 和 new.py 的内容相似。</li><li>这种方式更容易理解 <code>git checkout COMMIT_ID</code> 在做什么（重新应用 10000 个提交的想法让我感到很有压力）</li><li>合并提交在我看来更像是快照，因为合并的提交实际上可以是任何东西（它只是一个新的快照！）。它帮助我理解为什么在解决合并冲突时可以进行任意更改，以及为什么在解决冲突时要小心。</li></ul><h3 id="其他一些关于提交的理解" tabindex="-1">其他一些关于提交的理解 <a class="header-anchor" href="#其他一些关于提交的理解" aria-label="Permalink to “其他一些关于提交的理解”">​</a></h3><p>Mastodon 的一些回复中还提到了：</p><ul><li>有关提交的 “额外的” 带外信息，比如电子邮件、GitHub 拉取请求或者你和同事的对话</li><li>将“差异”视为一个“之前的状态 + 之后的状态”</li><li>以及，当然，很多人根据情况的不同以不同的方式看待提交</li></ul><p>人们在谈论提交时使用的其他一些词可能不那么含糊：</p><ul><li>“修订”（似乎更像是快照）</li><li>“补丁”（看起来更像是差异）</li></ul><h3 id="就到这里吧" tabindex="-1">就到这里吧！ <a class="header-anchor" href="#就到这里吧" aria-label="Permalink to “就到这里吧！”">​</a></h3><p>我很难了解人们对 Git 有哪些不同的理解。尤其棘手的是，尽管 “错误” 的理解往往非常有用，但人们却非常热衷于警惕 “错误” 的心智模式，所以人们不愿意分享他们 “错误” 的想法，生怕有什么 Git 解释者会站出来向他们解释为什么他们是错的。（这些 Git 解释者通常是出于善意的，但是无论如何它都会产生一种负面影响）</p><p>但是我学到了很多！我仍然不完全清楚该如何谈论提交，但是我们最终会弄清楚的。</p><p>感谢 Marco Rogers、Marie Flanagan 以及 Mastodon 上的所有人和我讨论 Git 提交。</p><p><em>（题图：DA/cc0cada9-4945-4248-8635-3f89dcebd6ef）</em></p><hr>',31)),i("p",null,[a[20]||(a[20]=s("via: ",-1)),l(t,{href:"https://jvns.ca/blog/2024/01/05/do-we-think-of-git-commits-as-diffs--snapshots--or-histories/"},{default:n(()=>[...a[19]||(a[19]=[s("https://jvns.ca/blog/2024/01/05/do-we-think-of-git-commits-as-diffs--snapshots--or-histories/",-1)])]),_:1})]),i("p",null,[a[25]||(a[25]=s("作者：",-1)),l(t,{href:"https://jvns.ca/"},{default:n(()=>[...a[21]||(a[21]=[s("Julia Evans",-1)])]),_:1}),a[26]||(a[26]=s(" 选题：",-1)),l(t,{href:"https://github.com/lujun9972"},{default:n(()=>[...a[22]||(a[22]=[s("lujun9972",-1)])]),_:1}),a[27]||(a[27]=s(" 译者：",-1)),l(t,{href:"https://github.com/Cubik65536"},{default:n(()=>[...a[23]||(a[23]=[s("Cubik65536",-1)])]),_:1}),a[28]||(a[28]=s(" 校对：",-1)),l(t,{href:"https://github.com/wxy"},{default:n(()=>[...a[24]||(a[24]=[s("wxy",-1)])]),_:1})]),i("p",null,[a[31]||(a[31]=s("本文由 ",-1)),l(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...a[29]||(a[29]=[s("LCTT",-1)])]),_:1}),a[32]||(a[32]=s(" 原创编译，",-1)),l(t,{href:"https://linux.cn/"},{default:n(()=>[...a[30]||(a[30]=[s("Linux中国",-1)])]),_:1}),a[33]||(a[33]=s(" 荣誉推出",-1))])])}const C=p(f,[["render",b]]);export{T as __pageData,C as default};
